#include "csv_util.h"

#include <fstream>
#include <vector>

namespace {

const std::streamoff CHUNK = 64 * 1024;

} // namespace

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::streamoff complete_file_size( const std::string & file )
{
    std::ifstream in( file, std::ios::binary );

    if( !in ) {
        return 0;
    }

    in.seekg( 0, std::ios::end );
    std::streamoff pos = (std::streamoff)in.tellg();

    if( pos <= 0 ) {
        return 0;
    }

    std::string buf;

    while( pos > 0 ) {
        const std::streamoff chunk = pos > CHUNK ? CHUNK : pos;
        const std::streamoff begin = pos - chunk;

        buf.resize( (std::size_t)chunk );
        in.seekg( begin, std::ios::beg );
        in.read( &buf[0], (std::streamsize)chunk );

        const std::size_t nl = buf.rfind( '\n' );

        if( nl != std::string::npos ) {
            return begin + (std::streamoff)nl + 1;
        }

        pos = begin;
    }

    return 0;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
std::streamoff find_import_start( const std::string & file, const std::string & newest_timestamp )
{
    if( newest_timestamp.empty() ) {
        return 0;   // empty database: import everything
    }

    CSVUtil csv( file );

    if( !csv ) {
        return -1;
    }

    const std::streamoff complete = complete_file_size( file );

    CSVUtil::reverse_iterator it = csv.rbegin();

    // A file that is still being written may end in a partial line. rbegin()
    // points at it, so step over it.
    if( complete < (std::streamoff)csv.getSize() && it != csv.rend() ) {
        ++it;
    }

    for( ; it != csv.rend(); ++it ) {
        const std::vector<std::string> fields = *it;

        if( fields.size() < DataRecord::MAX_FIELDS ) {
            continue;
        }

        const DataRecord rec( fields );

        if( rec.timestamp == 0 ) {
            continue;   // no usable date/time
        }

        if( rec.getRawDateTimeStr() <= newest_timestamp ) {
            return (std::streamoff)csv.getNextLinePos();
        }
    }

    return 0;   // nothing of the file is in the database yet
}
